-- Seed the Nairobi catalog from the current Fast Dine storefront data.
on conflict (id) do update set
  category_id = excluded.category_id, name = excluded.name, description = excluded.description,
  cuisine = excluded.cuisine, image_url = excluded.image_url, accent_color = excluded.accent_color,
  rating = excluded.rating, rating_count = excluded.rating_count,
  delivery_min_minutes = excluded.delivery_min_minutes, delivery_max_minutes = excluded.delivery_max_minutes,
  delivery_fee_kes = excluded.delivery_fee_kes, promo_text = excluded.promo_text,
  badge = excluded.badge, is_active = excluded.is_active;

on conflict (id) do update set
  store_id = excluded.store_id, name = excluded.name, description = excluded.description,
  price_kes = excluded.price_kes, old_price_kes = excluded.old_price_kes,
  image_url = excluded.image_url, tag = excluded.tag, is_available = excluded.is_available;
